async function syncWindowToDatabase(windowId) {
  if (!windowId || windowId < 0) return;
  try {
    try { await chrome.windows.get(windowId); } catch (e) { return; }
    let tabs = await chrome.tabs.query({ windowId: windowId });
    if (!tabs || tabs.length === 0) return;
    let grpMap = new Map();
    if (chrome.tabGroups) {
      try {
        let groups = await chrome.tabGroups.query({ windowId: windowId });
        for (let g of groups) grpMap.set(g.id, g);
      } catch(e) {}
    }
    let cleanTabs = [];
    for (let t of tabs) {
      let effectiveUrl = t.url || t.pendingUrl;
      if (!effectiveUrl || effectiveUrl.startsWith("chrome://newtab/")) continue;
      if (T.isTabSuspended({ url: effectiveUrl })) {
        let orig = T.getURLandTitleFromSuspendedUrl(effectiveUrl);
        if (!orig || !orig.url) continue;
        effectiveUrl = orig.url;
        t = { ...t, title: orig.title || t.title };
      } else if (effectiveUrl.startsWith("chrome-extension://")) {
        continue;
      }
      let tabObj = {
        title: t.title || effectiveUrl,
        url: effectiveUrl,
        pinned: !!t.pinned
      };
      if (t.groupId && t.groupId > 0 && grpMap.has(t.groupId)) {
        let grp = grpMap.get(t.groupId);
        tabObj.groupName = grp.title || "";
        tabObj.groupTitle = grp.title || "";
        tabObj.groupColor = grp.color || "blue";
        tabObj.groupCollapsed = !!grp.collapsed;
        tabObj.hasGroup = !0;
      }
      cleanTabs.push(tabObj);
    }
    let db = await xe;
    let tx = db.transaction(Y, "readwrite");
    let store = tx.store;
    let all = await store.getAll();
    let openedCl = all.find(c => c && c.windowId === windowId && !c.orphanedDate);
    if (!openedCl) {
      if (cleanTabs.length === 0) {
        await tx.done;
        return;
      }
      openedCl = F.createNewOpenedCluster(windowId, cleanTabs);
      openedCl.type = "found-as-a-new-one";
      let newId = await store.put(openedCl);
      openedCl._uid = newId;
    }
    let now = T.getDate().toISOString();
    let usedOld = new Set();
    for (let ct of cleanTabs) {
      let existing = openedCl.tabs?.find(et => et.url === ct.url && !usedOld.has(et));
      if (existing) usedOld.add(existing);
      ct._uid = existing?._uid || N.generateUniqueId();
      ct._addedDate = existing?._addedDate || now;
      ct._openedDate = existing?._openedDate || now;
      if (existing?.note) ct.note = existing.note;
    }
    openedCl.tabs = cleanTabs;
    openedCl._updatedDate = now;
    openedCl._modifiedDate = now;
    await store.put(openedCl);
    let targetSavedUid = openedCl.savedClusterUid;
    if (targetSavedUid) {
      let savedCl = await store.get(targetSavedUid);
      if (savedCl && !savedCl.windowId && !savedCl.orphanedDate) {
        let clonedTabs = JSON.parse(JSON.stringify(cleanTabs));
        savedCl.tabs = F.deleteUnneccessaryTabData(clonedTabs);
        savedCl._updatedDate = now;
        savedCl._modifiedDate = now;
        delete savedCl.orphanedDate;
        delete savedCl.windowId;
        await store.put(savedCl);
      }
    }
    await tx.done;
    Ne.sendMessage({ command: "clusters.db.updated" }, function(){});
  } catch (err) {
    console.warn("syncWindowToDatabase error:", err);
  }
}
